contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint attachedValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (attachedValue)); require(attachedValue <= 1000000000000000000000000000000);
        require(address(this).balance >= attachedValue, "insufficient balance");

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play{value: attachedValue}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        assert(
            (reverted && potAfter == potBefore) ||
            (!reverted && potAfter == 0) ||
            (!reverted && potAfter == potBefore + 10)
        );
    }

    receive() external payable {}
}

